from checked_integer import *
from typed_sequences import *
from file_identity import *
from ail import read_bytes, write_bytes
import sys

def main() -> int:
    if len(sys.argv) != 4:
        print('usage: integer_column_values input-path output-path zero-based-column', file=sys.stderr)
        return 2
    try:
        input: str = sys.argv[1]
        output: str = sys.argv[2]
        column: int = parse_int64_decimal(sys.argv[3])
        if column < 0 or input == output:
            raise ValueError
        if file_paths_same(input, output):
            raise ValueError
        data: bytes = read_bytes(input)
        text: str = data.decode()
        values: list[int] = integer_column_values(text, column)
        reversed: list[int] = integer_values_reverse(values)
        report: str = integer_values_render(reversed)
        write_bytes(output, report.encode())
        return 0
    except ValueError:
        print('invalid integer column or integer data', file=sys.stderr)
        return 2
    except IndexError:
        print('integer column is missing', file=sys.stderr)
        return 2
    except OSError:
        print('integer column file error', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
